/**
 * Golden fixtures: one real response per platform, parsed and asserted in full.
 *
 * Every way this scraper breaks, it breaks quietly. A school re-themes its schedule page
 * and the row selector matches nothing; a JSON field is renamed and every score comes
 * back null; an opponent stops resolving and half a season files itself under two names.
 * None of that raises. The stage exits 0, writes fewer or emptier rows than it did
 * yesterday, and the pipeline carries on to rate teams on a dataset that quietly lost a
 * conference. The only way to see it is to have written the answer down first.
 *
 * So each of the six fixtures in `packages/parsers/src/__fixtures__` is parsed here and
 * compared against its complete output — every row, every field, serialised as JSON so
 * that nothing can be added, dropped or reordered without the diff saying so. Asserting
 * a count instead would pass for any of the failures above that keeps the row count.
 *
 * The parsers are driven exactly as `fetch_schedules_parallel.ts` and
 * `fetch_boxscores_from_csv.ts` drive them, down to the real `TeamNameResolver` built
 * from `data/teams`. That is deliberate: canonicalisation is part of what silently
 * degrades, and a test that injects an empty resolver would not notice an alias
 * disappearing. It does mean an inventory edit can move these expectations — legitimately
 * — so read the diff rather than regenerating past it.
 *
 * Every fixture is the 2025 season, which is over. A correct parser returns these exact
 * rows forever.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import * as fs from 'fs';
import * as path from 'path';
import { Game, GameSchema, PlayerStat, PlayerStatSchema } from '@ncaa/shared';
import {
    SidearmBoxScoreParser,
    SidearmParser,
    WmtBoxScoreParser,
    WmtParser,
    WmtWordpressParser
} from '@ncaa/parsers';
import { REPO_ROOT } from '@ncaa/storage';
import { buildTeamNameResolver, loadAllTeams } from '../utils/teams';

const FIXTURES = path.join(REPO_ROOT, 'packages/parsers/src/__fixtures__');
const fixture = (name: string): string => fs.readFileSync(path.join(FIXTURES, name), 'utf8');

/** The resolver the pipeline runs with: every alias of every school in the inventory. */
const resolver = buildTeamNameResolver(loadAllTeams());

/**
 * One line per row, lossless.
 *
 * `JSON.stringify` rather than a hand-written formatter because a formatter is a second
 * place to forget a field: it would keep passing after the parser stopped setting
 * `game_type`, which is the exact class of silence these fixtures exist to break.
 */
const lines = (rows: unknown[]): string[] => rows.map(row => JSON.stringify(row));

/** Rows the pipeline would refuse to store are a failure however well they compare. */
function assertValidGames(games: Game[]): void {
    for (const game of games) {
        const parsed = GameSchema.safeParse(game);
        assert.ok(parsed.success, `${game.game_id}: ${JSON.stringify((parsed as any).error?.issues)}`);
    }
}

function assertValidPlayerStats(stats: PlayerStat[]): void {
    for (const stat of stats) {
        const parsed = PlayerStatSchema.safeParse(stat);
        assert.ok(parsed.success, `${stat.player_key}: ${JSON.stringify((parsed as any).error?.issues)}`);
    }
}


