/**
 * The two box scores agree with the two schedules on the same fixture.
 *
 * Each half of this is asserted above already; what it adds is the join. A parser can be
 * internally consistent and still put the goals on the wrong side, and the only place
 * that shows is where two sources describe one game — Clemson's schedule row says it beat
 * South Carolina 4-1 at home, and the stats feed for that game has to say the same. This
 * is also the check that survives a fixture refresh, since it compares two files rather
 * than either file to a literal.
 */
test('the schedule row and the box score tell the same story about one fixture', () => {
    const clemson = CLEMSON_SCHEDULE.map(line => JSON.parse(line) as Game).find(
        game => game.date === '2025-08-26'
    );
    assert.ok(clemson, 'Clemson v South Carolina should be in the parsed schedule');

    const box = new WmtBoxScoreParser().parseStats(
        JSON.parse(fixture('wmt_stats_clemson_south_carolina_2025.json')),
        { nameResolver: resolver }
    );

    assert.equal(clemson.home_team_name, box.game.home_team_name);
    assert.equal(clemson.away_team_name, box.game.away_team_name);
    assert.equal(clemson.home_score, box.game.home_score);
    assert.equal(clemson.away_score, box.game.away_score);

    // The scorers add up to the scoreline: a box score that dropped one team's rows would
    // still parse, and would still look like a box score.
    const goals = (team: string): number =>
        box.playerStats
            .filter(stat => stat.team_id === team)
            .reduce((sum, stat) => sum + (stat.goals || 0), 0);
    assert.equal(goals('Clemson'), 4);
    assert.equal(goals('South Carolina'), 1);
});
